def relay(ref, value, x, y, coil_hi, coil_lo, com, no, nc, note):
    k = s.place(RLY, ref, value, x, y)
    s.stub(k['A1'], coil_hi)
    s.stub(k['A2'], coil_lo)
    if com: s.stub(k['11'], com)
    if no:  s.stub(k['14'], no)
    if nc:  s.stub(k['12'], nc)
    s.text(note, x - 14, y + 16, 1.4, False)
    return k

